// R4 smoke test: Wild battle level-up, evolution scene, overworld return and save persistence.
// PREPARED: Route 1 tall grass start with a Lv15 Bulbasaur 1 exp point below Lv16.
// The encounter is generated by the engine; the battle is fought with first move (Tackle);
// the level-up and evolution run the faithful source scenes, return to field, save and reload.

export default async function run(ctx) {
  const p = ctx.page;
  await p.goto(new URL('viewer.html#modo=explore&mapa=MAP_ROUTE1&px=14&py=-14', process.env.PW_BASE ?? 'http://localhost:5173').href);
  await p.waitForFunction(() => performance.getEntriesByName('viewer-interactive').length);

  // PREPARED: Lead Bulbasaur L15 with experience 1 point below evolution level 16
  await p.evaluate(async () => {
    const { save } = await import('/src/games/firered/save.ts');
    const { createMon, expForLevel } = await import('/src/core/pokemon/pokemon.ts');
    const mon = createMon(1, 15);
    mon.exp = expForLevel(1, 16) - 1;
    mon.moves = [33, 45, 73, 22]; // Tackle, Growl, Leech Seed, Vine Whip
    mon.pp = [35, 40, 10, 25];
    save.party[0] = mon;
  });

  const snap = () => p.evaluate(async () => {
    const { save } = await import('/src/games/firered/save.ts');
    const { getDexFlag } = await import('/src/core/pokemon/pokemon.ts');
    const m = save.party[0];
    return {
      species: m.species,
      level: m.level,
      exp: m.exp,
      moves: [...m.moves],
      ivysaurCaught: getDexFlag(2, true),
      loc: save.location,
    };
  });

  const before = await snap();
  await p.locator('#viewport').focus();
  const visible = () => p.locator('#engine-interaction').isVisible();

  // Walk in tall grass to trigger wild encounter
  let steps = 0;
  for (; steps < 300 && !await visible(); steps++) {
    const k = (steps >> 2) % 2 ? 'ArrowUp' : 'ArrowDown';
    await p.keyboard.down(k);
    await p.waitForTimeout(150);
    await p.keyboard.up(k);
    await p.waitForTimeout(320);
  }
  if (!await visible()) throw new Error('No wild encounter in ' + steps + ' steps');
  await ctx.shot('r4-encounter');

  // Fight battle, advance level-up window and evolution scene with 'z'
  let presses = 0;
  for (; presses < 400 && await visible(); presses++) {
    await p.keyboard.press('z');
    await p.waitForTimeout(500);
    if (presses === 15) await ctx.shot('r4-battle');
    if (presses === 40) await ctx.shot('r4-evo');
  }
  if (await visible()) throw new Error('Battle and evolution did not return to overworld in ' + presses + ' presses');
  await p.waitForTimeout(1500);
  await ctx.shot('r4-returned');

  const afterBattle = await snap();
  if (afterBattle.species !== 2) throw new Error('Bulbasaur did not evolve to Ivysaur (species 2): ' + JSON.stringify(afterBattle));
  if (afterBattle.level !== 16) throw new Error('Level is not 16: ' + JSON.stringify(afterBattle));
  if (!afterBattle.ivysaurCaught) throw new Error('Ivysaur pokedex caught flag not set: ' + JSON.stringify(afterBattle));

  // The player must be able to walk in the overworld after returning
  const hashBefore = await p.evaluate(() => location.hash);
  await p.locator('#viewport').focus();
  await p.keyboard.down('ArrowRight');
  await p.waitForTimeout(150);
  await p.keyboard.up('ArrowRight');
  await p.waitForTimeout(500);
  await p.keyboard.down('ArrowRight');
  await p.waitForTimeout(500);
  await p.keyboard.up('ArrowRight');
  await p.waitForTimeout(600);
  const moved = await p.evaluate(() => location.hash) !== hashBefore;

  // Save via the viewer DOM menu and reload to verify persistence
  await p.getByRole('button', { name: "Menu · Esc" }).click();
  await p.locator('#explore-save').click();
  await p.keyboard.press('Escape');
  await p.waitForTimeout(500);

  await p.reload();
  await p.waitForFunction(() => performance.getEntriesByName('viewer-interactive').length);
  const persisted = await snap();

  if (persisted.species !== 2) throw new Error('Evolved species 2 not persisted across reload: ' + JSON.stringify(persisted));
  if (persisted.level !== 16) throw new Error('Level 16 not persisted across reload: ' + JSON.stringify(persisted));
  if (!persisted.ivysaurCaught) throw new Error('Pokedex caught flag not persisted: ' + JSON.stringify(persisted));

  return {
    steps,
    presses,
    before,
    afterBattle,
    persisted,
    movedAfterBattle: moved,
    errors: ctx.errors(),
  };
}
